// Writes src/agent.generated.ts from the agent's JSON Schema (ADR 0104):
//   pnpm --filter @atlas/shared generate:agent
// It supports only the keywords the contract uses and throws, naming the keyword and its path,
// on anything else.
// Node
import { readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'

type Node = Record< string, unknown >
export type Contract = { $defs: Record< string, Node > }

const HEADER = [
  '// Generated by `pnpm --filter @atlas/shared generate:agent` from',
  '// apps/agent/schema/*_contract.json. Do not edit by hand (ADR 0104).',
].join( '\n' )

const REF_PREFIX = '#/$defs/'

type Rendered = { code: string, refs: string[] }

const fail = ( message: string, path: string ): never => {
  throw new Error( `${ message } at ${ path }` )
}

const text = ( value: unknown ): string => JSON.stringify( value ).replace( /"/g, '\'' )

const nameOf = ( reference: string ): string => reference.slice( REF_PREFIX.length )

const limit = ( method: string, value: unknown ): string => (
  typeof value === 'number' ? `.${ method }( ${ value } )` : ''
)

const renderNode = ( node: Node, path: string, indent: string ): Rendered => {
  const rest = new Map( Object.entries( node ) )
  const take = ( key: string ): unknown => {
    const value = rest.get( key )
    rest.delete( key )
    return value
  }
  const finish = ( rendered: Rendered ): Rendered => {
    rest.delete( 'title' )
    const [ keyword ] = rest.keys()
    if( keyword !== undefined ) fail( `unsupported keyword ${ keyword }`, path )
    return rendered
  }
  const child = ( value: unknown, childPath: string, childIndent = indent ): Rendered => (
    renderNode( value as Node, childPath, childIndent )
  )

  if( rest.has( '$ref' ) ) {
    const name = nameOf( take( '$ref' ) as string )
    return finish( { code: name, refs: [ name ] } )
  }

  if( rest.has( 'anyOf' ) ) {
    const options = take( 'anyOf' ) as Node[]
    const other = options.find( ( option ) => option.type !== 'null' )
    const hasNull = options.some( ( option ) => option.type === 'null' )
    if( options.length !== 2 || !hasNull || other === undefined ) {
      fail( 'unsupported keyword anyOf (only X or null)', path )
    }
    const inner = child( other, `${ path }/anyOf` )
    return finish( { code: `${ inner.code }.nullable()`, refs: inner.refs } )
  }

  if( rest.has( 'oneOf' ) ) {
    const options = take( 'oneOf' ) as Node[]
    const discriminator = take( 'discriminator' ) as { propertyName: string } | undefined
    if( discriminator === undefined ) {
      fail( 'unsupported keyword oneOf (needs a discriminator)', path )
    }
    const names = options.map( ( option, index ) => {
      if( typeof option.$ref !== 'string' ) {
        fail( 'oneOf options must be $ref', `${ path }/oneOf/${ index }` )
      }
      return nameOf( option.$ref as string )
    } )
    const lines = names.map( ( name ) => `${ indent }  ${ name },` ).join( '\n' )
    const property = text( discriminator?.propertyName )
    const code = `z.discriminatedUnion( ${ property }, [\n${ lines }\n${ indent }] )`
    return finish( { code, refs: names } )
  }

  const type = take( 'type' )

  if( type === 'null' ) return finish( { code: 'z.null()', refs: [] } )
  if( type === 'integer' ) return finish( { code: 'z.number().int()', refs: [] } )

  if( type === 'string' ) {
    if( rest.has( 'const' ) ) {
      return finish( { code: `z.literal( ${ text( take( 'const' ) ) } )`, refs: [] } )
    }
    if( rest.has( 'enum' ) ) {
      const values = ( take( 'enum' ) as string[] ).map( text ).join( ', ' )
      return finish( { code: `z.enum( [ ${ values } ] )`, refs: [] } )
    }
    const minimum = limit( 'min', take( 'minLength' ) )
    const maximum = limit( 'max', take( 'maxLength' ) )
    const pattern = take( 'pattern' )
    const source = typeof pattern === 'string' ? escapeSlashes( pattern ) : ''
    const regex = typeof pattern === 'string' ? `.regex( /${ source }/ )` : ''
    const code = `z.string()${ minimum }${ maximum }${ regex }`
    return finish( { code, refs: [] } )
  }

  if( type === 'array' ) {
    const items = child( take( 'items' ), `${ path }/items` )
    const maximum = limit( 'max', take( 'maxItems' ) )
    return finish( { code: `z.array( ${ items.code } )${ maximum }`, refs: items.refs } )
  }

  if( type === 'object' ) {
    const properties = take( 'properties' ) as Record< string, Node >
    const required = take( 'required' ) as string[]
    const refs: string[] = []
    const lines = Object.entries( properties ).map( ( [ name, property ] ) => {
      if( !required.includes( name ) ) fail( `${ name } is not required`, path )
      const rendered = child( property, `${ path }/properties/${ name }`, `${ indent }  ` )
      refs.push( ...rendered.refs )
      return `${ indent }  ${ name }: ${ rendered.code },`
    } )
    return finish( { code: `z.object( {\n${ lines.join( '\n' ) }\n${ indent }} )`, refs } )
  }

  if( type === undefined ) {
    finish( { code: '', refs: [] } )
    return fail( 'unsupported schema (no type)', path )
  }

  return fail( `unsupported type ${ JSON.stringify( type ).replace( /"/g, '' ) }`, path )
}

const orderDefinitions = ( rendered: Map< string, Rendered > ): string[] => {
  const ordered: string[] = []
  const state = new Map< string, 'visiting' | 'done' >()
  const visit = ( name: string, trail: string[] ): void => {
    if( state.get( name ) === 'done' ) return
    if( state.get( name ) === 'visiting' ) {
      throw new Error( `cycle in the contract: ${ [ ...trail, name ].join( ' -> ' ) }` )
    }
    state.set( name, 'visiting' )
    for( const reference of rendered.get( name )?.refs ?? [] ) {
      visit( reference, [ ...trail, name ] )
    }
    state.set( name, 'done' )
    ordered.push( name )
  }
  for( const name of [ ...rendered.keys() ].sort() ) visit( name, [] )
  return ordered
}

// A slash ends a regex literal, except inside a character class, where escaping it is a lint error
const escapeSlashes = ( pattern: string ): string => {
  let inClass = false
  let output = ''

  for( let index = 0; index < pattern.length; index += 1 ) {
    const character = pattern.charAt( index )

    if( character === '\\' ) {
      output += character + pattern.charAt( index + 1 )
      index += 1
      continue
    }

    if( character === '[' ) inClass = true
    if( character === ']' ) inClass = false

    output += character === '/' && !inClass ? '\\/' : character
  }

  return output
}

export const generateAgentContract = ( contracts: Contract[] ): string => {
  const definitions = new Map< string, Node >()
  for( const contract of contracts ) {
    for( const [ name, node ] of Object.entries( contract.$defs ) ) {
      if( definitions.has( name ) ) {
        throw new Error( `${ name } is defined in more than one contract` )
      }
      definitions.set( name, node )
    }
  }

  const rendered = new Map< string, Rendered >()
  for( const [ name, node ] of definitions ) {
    rendered.set( name, renderNode( node, `${ REF_PREFIX }${ name }`, '' ) )
  }
  for( const [ name, { refs } ] of rendered ) {
    const missing = refs.find( ( reference ) => !definitions.has( reference ) )
    if( missing !== undefined ) {
      fail( `reference to ${ missing }, which is not defined`, `${ REF_PREFIX }${ name }` )
    }
  }

  const blocks = orderDefinitions( rendered ).map( ( name ) => [
    `export const ${ name } = ${ rendered.get( name )?.code ?? '' }`,
    `export type ${ name } = z.infer< typeof ${ name } >`,
  ].join( '\n' ) )

  const intro = `${ HEADER }\n\n// Packages\nimport { z } from 'zod'`

  return `${ [ intro, ...blocks ].join( '\n\n' ) }\n`
}

const main = (): void => {
  const root = fileURLToPath( new URL( '..', import.meta.url ) )
  const schemaFolder = join( root, '..', '..', 'apps', 'agent', 'schema' )
  const contracts = readdirSync( schemaFolder )
    .filter( ( file ) => file.endsWith( '_contract.json' ) )
    .sort()
    .map( ( file ) => JSON.parse( readFileSync( join( schemaFolder, file ), 'utf8' ) ) as Contract )

  writeFileSync( join( root, 'src', 'agent.generated.ts' ), generateAgentContract( contracts ) )
}

if( process.argv[ 1 ] === fileURLToPath( import.meta.url ) ) main()
